 SecretKey key()throws Exception {KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);if(!k.containsAlias("arhilab-data")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("arhilab-data",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes("GCM").setEncryptionPaddings("NoPadding").build());g.generateKey();}return (SecretKey)k.getKey("arhilab-data",null);}
 String tokenHash(byte[] token)throws Exception{return Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(token));}
 void startSession()throws Exception{byte[] token=new byte[32];new SecureRandom().nextBytes(token);user().put("sessionHash",tokenHash(token));saveRaw();Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());File tmp=new File(getFilesDir(),"session.tmp"),target=new File(getFilesDir(),"session.enc");try(FileOutputStream o=new FileOutputStream(tmp)){o.write(c.getIV());o.write(c.doFinal(new JSONObject().put("user",userId).put("token",Base64.getEncoder().encodeToString(token)).toString().getBytes(StandardCharsets.UTF_8)));o.getFD().sync();}if(!tmp.renameTo(target))throw new IOException("Не удалось сохранить сессию");Arrays.fill(token,(byte)0);}
 void loadSession(){File f=new File(getFilesDir(),"session.enc");if(!f.exists())return;try{byte[] all=java.nio.file.Files.readAllBytes(f.toPath());if(all.length<29)throw new IOException("Сессия повреждена");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(all,0,12)));JSONObject s=new JSONObject(new String(c.doFinal(Arrays.copyOfRange(all,12,all.length)),StandardCharsets.UTF_8));JSONObject u=find(db.getJSONArray("users"),s.getString("user"));byte[] token=Base64.getDecoder().decode(s.getString("token"));if(token.length!=32||!MessageDigest.isEqual(tokenHash(token).getBytes(StandardCharsets.UTF_8),u.optString("sessionHash").getBytes(StandardCharsets.UTF_8)))throw new IOException("Сессия отозвана");userId=u.getString("id");Arrays.fill(token,(byte)0);}catch(Exception e){userId=null;f.delete();}}
