 void saveRaw()throws Exception{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key());byte[] enc=c.doFinal(db.toString().getBytes(StandardCharsets.UTF_8));File f=new File(getFilesDir(),"data.enc"),tmp=new File(getFilesDir(),"data.tmp");try(FileOutputStream o=new FileOutputStream(tmp)){o.write(c.getIV());o.write(enc);o.getFD().sync();}if(f.exists()){File backup=new File(getFilesDir(),"data-previous.enc");java.nio.file.Files.copy(f.toPath(),backup.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}if(!tmp.renameTo(f))throw new IOException("Не удалось сохранить данные");}
 void load()throws Exception{catalog=new JSONObject(read(getAssets().open("catalog.json")));File update=new File(getFilesDir(),"catalog-update.json");if(update.exists()){try{JSONObject latest=new JSONObject(new String(java.nio.file.Files.readAllBytes(update.toPath()),StandardCharsets.UTF_8));validateCatalog(latest);catalog=latest;}catch(Exception e){startupWarning="Обновлённый прайс не открывается; загружен встроенный каталог: "+e.getMessage();}}File f=new File(getFilesDir(),"data.enc");if(!f.exists()){db=new JSONObject().put("users",new JSONArray()).put("projects",new JSONArray());return;}byte[] all=java.nio.file.Files.readAllBytes(f.toPath());if(all.length<29)throw new IOException("Файл базы повреждён");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Arrays.copyOfRange(all,0,12)));JSONObject original=new JSONObject(new String(c.doFinal(Arrays.copyOfRange(all,12,all.length)),StandardCharsets.UTF_8));db=original;JSONObject updated=new JSONObject(original.toString());MigrationReport report=migratePhotos(updated,true);if(report.failed>0)startupWarning="Не удалось перенести "+report.failed+" фото. Объекты доступны; исходные данные фото сохранены. Первое проблемное фото: "+report.firstFailure+". Сделайте резервную копию в настройках.";if(report.migrated>0){db=updated;try{save();}catch(Exception e){db=original;startupWarning="Объекты доступны, но перенос фото пока не сохранён: "+e.getMessage()+". Не удаляйте приложение; сделайте резервную копию.";}}loadSession();}
 PhotoStore photos()throws Exception{if(images==null)images=new PhotoStore(new File(getFilesDir(),"images"),key());return images;}
 byte[] photoBytes(String data)throws Exception{String prefix="data:image/jpeg;base64,";if(!data.startsWith(prefix))throw new IOException("Некорректный формат фото");byte[] bytes=Base64.getDecoder().decode(data.substring(prefix.length()));if(bytes.length<4||(bytes[0]&255)!=255||(bytes[1]&255)!=216||(bytes[bytes.length-2]&255)!=255||(bytes[bytes.length-1]&255)!=217)throw new IOException("Повреждённый JPEG");return bytes;}
 static class MigrationReport{int migrated,failed;String firstFailure="";}
 MigrationReport migratePhotos(JSONObject database,boolean keepFailures)throws Exception{MigrationReport result=new MigrationReport();JSONArray projects=database.getJSONArray("projects");for(int i=0;i<projects.length();i++){JSONObject p=projects.getJSONObject(i);for(String arr:new String[]{"photos","estimatePhotos"}){JSONArray list=p.optJSONArray(arr);if(list==null)continue;for(int j=0;j<list.length();j++){try{JSONObject row=list.getJSONObject(j);if(!row.has("data"))continue;byte[] jpeg=photoBytes(row.getString("data"));String id=row.optString("id");if(!id.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}"))id=UUID.randomUUID().toString();photos().put(id,jpeg);row.put("id",id);row.remove("data");result.migrated++;}catch(Exception e){if(!keepFailures)throw e;result.failed++;if(result.firstFailure.isEmpty())result.firstFailure=p.optString("name","Объект")+", "+(arr.equals("photos")?"фото объекта":"фото сметы")+" №"+(j+1)+" ("+e.getMessage()+")";}}}}return result;}
 JSONArray photoPayload(JSONObject p,String arr)throws Exception{JSONArray source=p.optJSONArray(arr),out=new JSONArray();if(source==null)return out;for(int i=0;i<source.length();i++){try{JSONObject row=new JSONObject(source.getJSONObject(i).toString());if(!row.has("data"))row.put("data","data:image/jpeg;base64,"+Base64.getEncoder().encodeToString(photos().get(row.getString("id"))));photoBytes(row.getString("data"));out.put(row);}catch(Exception ignored){/* Keep the record in db; skip only its unavailable image in the view/export. */}}return out;}
 JSONObject backupContent()throws Exception{JSONObject out=new JSONObject().put("format","Arhilab-1").put("team",state().getJSONArray("users"));JSONArray projects=new JSONArray();JSONArray source=db.getJSONArray("projects");skippedBackupPhotos=0;for(int i=0;i<source.length();i++){JSONObject p=new JSONObject(source.getJSONObject(i).toString());for(String arr:new String[]{"photos","estimatePhotos"})if(p.has(arr)){JSONArray original=p.getJSONArray(arr),available=photoPayload(p,arr);skippedBackupPhotos+=original.length()-available.length();p.put(arr,available);}projects.put(p);}return out.put("projects",projects).put("catalog",catalog);}
 public void onCreate(Bundle b){super.onCreate(b);try{load();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Ошибка открытия базы").setMessage("Данные не перезаписаны. "+e.getMessage()).setPositiveButton("Закрыть",(d,w)->finish()).show();return;}web=new WebView(this);web.setBackgroundColor(0xfff2f3ef);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setDomStorageEnabled(false);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}public void onPageFinished(WebView v,String url){if(!startupWarning.isEmpty()){String message=startupWarning;startupWarning="";new AlertDialog.Builder(MainActivity.this).setTitle("Проверка фотографий").setMessage(message).setPositiveButton("Понятно",null).show();}}});web.setWebChromeClient(new WebChromeClient());web.addJavascriptInterface(new Bridge(),"Native");setContentView(web);web.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(in.getSystemWindowInsetLeft(),in.getSystemWindowInsetTop(),in.getSystemWindowInsetRight(),in.getSystemWindowInsetBottom());return in.consumeSystemWindowInsets();});web.loadUrl("file:///android_asset/index.html");}
 JSONObject find(JSONArray a,String id)throws Exception{for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optString("id").equals(id))return a.getJSONObject(i);throw new Exception("Запись не найдена");}
