 String hash(String pw,String salt)throws Exception{PBEKeySpec p=new PBEKeySpec(pw.toCharArray(),Base64.getDecoder().decode(salt),120000,256);return Base64.getEncoder().encodeToString(SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256").generateSecret(p).getEncoded());}
 void password(JSONObject u,String pw)throws Exception{if(pw.length()<8)throw new Exception("Пароль: минимум 8 символов");byte[] b=new byte[16];new SecureRandom().nextBytes(b);String salt=Base64.getEncoder().encodeToString(b);u.put("salt",salt).put("hash",hash(pw,salt));}
