 JSONObject readBackup(Uri uri)throws Exception{byte[] contents=readBytes(getContentResolver().openInputStream(uri));if(BackupCrypto.isEncrypted(contents)){if(pendingRestorePassword==null)throw new Exception("Введите пароль копии");try{contents=BackupCrypto.decrypt(contents,pendingRestorePassword);}catch(javax.crypto.AEADBadTagException e){throw new Exception("Неверный пароль или повреждённая копия");}}else if(contents.length==0||contents[0]!='{')throw new Exception("Неизвестный формат файла");JSONObject backup=new JSONObject(new String(contents,StandardCharsets.UTF_8));if(!backup.optString("format").equals("Arhilab-1"))throw new Exception("Неизвестный формат копии");return backup;}
 int validateBackup(JSONObject backup)throws Exception{int imageCount=0;JSONArray imported=backup.getJSONArray("projects");for(int i=0;i<imported.length();i++){JSONObject p=imported.getJSONObject(i);if(!p.getString("id").matches("[a-f0-9-]{36}"))throw new Exception("Некорректный ID объекта");p.getString("name");for(String arr:new String[]{"lines","materials","tasks","payments","notes","photos","estimatePhotos"}){JSONArray rows=arr.equals("estimatePhotos")?p.optJSONArray(arr):p.getJSONArray(arr);if(rows==null)continue;for(int j=0;j<rows.length();j++){JSONObject row=rows.getJSONObject(j);if(row.has("id")&&!row.getString("id").matches("[a-f0-9-]{36}"))throw new Exception("Некорректный ID записи");if(arr.equals("photos")||arr.equals("estimatePhotos")){photoBytes(row.optString("data"));imageCount++;}}}}return imageCount;}
 protected void onActivityResult(int req,int result,Intent intent){
  super.onActivityResult(req,result,intent);
  if(result!=RESULT_OK||intent==null){if(req==11)exportBytes=null;if((req==12||req==15)&&pendingRestorePassword!=null){Arrays.fill(pendingRestorePassword,'\0');pendingRestorePassword=null;}return;}
  try{
   if(req==11){admin();if(exportBytes==null)throw new Exception("Копия не подготовлена");try(OutputStream o=getContentResolver().openOutputStream(intent.getData())){o.write(exportBytes);}exportBytes=null;notifyJs("Защищённая копия сохранена");}
   if(req==12||req==15){
    admin();JSONObject backup=readBackup(intent.getData());int imageCount=validateBackup(backup);JSONArray imported=backup.getJSONArray("projects");
    if(req==15){new AlertDialog.Builder(this).setTitle("Копия прошла проверку").setMessage("Объектов: "+imported.length()+". Фотографий: "+imageCount+". Пароль подходит, структура копии читается. Данные телефона не изменены.").setPositiveButton("Закрыть",null).show();return;}
    new AlertDialog.Builder(this).setTitle("Восстановить объекты?").setMessage("Объекты на телефоне будут заменены данными копии. Учётные записи останутся прежними.").setNegativeButton("Отмена",null).setPositiveButton("Восстановить",(d,w)->{
     JSONObject old=db;try{admin();JSONObject next=new JSONObject(db.toString());JSONArray fresh=new JSONArray(imported.toString());for(int i=0;i<fresh.length();i++){JSONObject p=fresh.getJSONObject(i);for(String arr:new String[]{"photos","estimatePhotos"}){JSONArray rows=p.optJSONArray(arr);if(rows!=null)for(int j=0;j<rows.length();j++)rows.getJSONObject(j).put("id",UUID.randomUUID().toString());}}
      next.put("projects",fresh);db=next;migratePhotos(db,false);save();notifyJs("Объекты восстановлены");
     }catch(Exception e){db=old;notifyJs("Ошибка восстановления: "+e.getMessage());}
    }).show();
   }
   if(req==16){admin();byte[] bytes=readBytes(getContentResolver().openInputStream(intent.getData()));if(bytes.length>5000000)throw new Exception("Прайс слишком большой");JSONObject updated=new JSONObject(new String(bytes,StandardCharsets.UTF_8));storeCatalog(updated);notifyJs("Прайс обновлён: "+updated.getJSONArray("materials").length()+" SKU");}
   if(req==13||req==14||req==18){
    if(req==14)editor();JSONObject p=project(pendingProject);String collection=req==14?"estimatePhotos":"photos";JSONArray target=p.optJSONArray(collection);if(target==null){target=new JSONArray();p.put(collection,target);}if(req==14&&target.length()>=12)throw new Exception("Не более 12 фото в одной смете");
    android.graphics.BitmapFactory.Options opts=new android.graphics.BitmapFactory.Options();opts.inJustDecodeBounds=true;try(InputStream in=getContentResolver().openInputStream(intent.getData())){android.graphics.BitmapFactory.decodeStream(in,null,opts);}opts.inSampleSize=1;while(Math.max(opts.outWidth,opts.outHeight)/opts.inSampleSize>(req==14?1200:1600))opts.inSampleSize*=2;opts.inJustDecodeBounds=false;
    android.graphics.Bitmap bitmap;try(InputStream in=getContentResolver().openInputStream(intent.getData())){bitmap=android.graphics.BitmapFactory.decodeStream(in,null,opts);}if(bitmap==null)throw new Exception("Не удалось открыть фото");ByteArrayOutputStream bytes=new ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,req==14?72:80,bytes);bitmap.recycle();if(bytes.size()>1500000)throw new Exception("Фото слишком большое: выберите изображение меньшего размера");
    String id=UUID.randomUUID().toString();photos().put(id,bytes.toByteArray());JSONObject record=new JSONObject().put("id",id).put("date",new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.ROOT).format(new Date()));if(req==18)record.put("purchaseRef",pendingReceiptRef).put("documentType",pendingReceiptType);target.put(record);save();notifyJs(req==18?"Документ закупки добавлен":req==14?"Фото добавлено в смету":"Фото добавлено");
   }
  }catch(Exception e){notifyJs("Ошибка: "+e.getMessage());}
  finally{if((req==12||req==15)&&pendingRestorePassword!=null){Arrays.fill(pendingRestorePassword,'\0');pendingRestorePassword=null;}if(req==11)exportBytes=null;}
 }
